#!/usr/bin/env python3
# OTP CENTER (clean edition) - self-issued one-time codes for the owner's own shop.
# Server-side only logic: stdlib only (http.server + sqlite3), no external deps.
# Codes are generated by THIS server, bound to an order + customer. No third-party
# mailbox tokens are imported and no external mailbox is ever read.
import hashlib, hmac, json, os, secrets, sqlite3, time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse

DB_PATH = os.environ.get("OTP_DB", os.path.join(os.path.dirname(os.path.abspath(__file__)), "otp.db"))
PORT = int(os.environ.get("PORT", "8080"))
PBKDF2_ROUNDS = 200_000
SESSION_TTL = 7 * 24 * 3600

def now():
    return int(time.time())

def pw_hash(password, salt=None):
    salt = salt or secrets.token_hex(16)
    dk = hashlib.pbkdf2_hmac("sha256", password.encode(), bytes.fromhex(salt), PBKDF2_ROUNDS)
    return salt, dk.hex()

def pw_check(password, salt, expected):
    _, got = pw_hash(password, salt)
    return hmac.compare_digest(got, expected)

def code_hash(code, order_no):
    return hashlib.sha256(f"{order_no}:{code}".encode()).hexdigest()

def db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    c = db()
    c.executescript("""
    CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT);
    CREATE TABLE IF NOT EXISTS admin(id INTEGER PRIMARY KEY CHECK(id=1), salt TEXT, pass_hash TEXT);
    CREATE TABLE IF NOT EXISTS customers(id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE NOT NULL,
        display_name TEXT, salt TEXT, pass_hash TEXT, active INTEGER DEFAULT 1, created_at INTEGER);
    CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, role TEXT, customer_id INTEGER, expires INTEGER);
    CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT, order_no TEXT UNIQUE NOT NULL,
        customer_id INTEGER NOT NULL, item TEXT, note TEXT, status TEXT DEFAULT '进行中', created_at INTEGER);
    CREATE TABLE IF NOT EXISTS codes(id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL,
        customer_id INTEGER NOT NULL, code_hash TEXT NOT NULL, status TEXT DEFAULT '有效',
        created_at INTEGER, expires_at INTEGER, used_at INTEGER);
    CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER, actor TEXT, action TEXT, detail TEXT);
    """)
    for k, v in (("ttl_minutes", "5"), ("per_hour_limit", "5"), ("site_name", "OTP CENTER")):
        c.execute("INSERT OR IGNORE INTO settings(key,value) VALUES(?,?)", (k, v))
    c.commit(); c.close()

def get_setting(c, key, default=""):
    row = c.execute("SELECT value FROM settings WHERE key=?", (key,)).fetchone()
    return row["value"] if row else default

def audit(c, actor, action, detail=""):
    c.execute("INSERT INTO audit(ts,actor,action,detail) VALUES(?,?,?,?)", (now(), actor, action, detail))

def make_session(c, role, customer_id=None):
    token = secrets.token_urlsafe(32)
    th = hashlib.sha256(token.encode()).hexdigest()
    c.execute("INSERT INTO sessions(token_hash,role,customer_id,expires) VALUES(?,?,?,?)",
              (th, role, customer_id, now() + SESSION_TTL))
    return token

def read_session(c, handler):
    cookie = handler.headers.get("Cookie", "") or ""
    token = None
    for part in cookie.split(";"):
        part = part.strip()
        if part.startswith("otp_session="):
            token = part[len("otp_session="):]
    if not token:
        return None
    th = hashlib.sha256(token.encode()).hexdigest()
    row = c.execute("SELECT * FROM sessions WHERE token_hash=?", (th,)).fetchone()
    if not row or row["expires"] < now():
        return None
    return row

def expire_codes(c):
    c.execute("UPDATE codes SET status='已过期' WHERE status='有效' AND expires_at < ?", (now(),))

class Handler(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def send_json(self, data, status=200, cookie=None):
        body = json.dumps(data, ensure_ascii=False).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        if cookie is not None:
            self.send_header("Set-Cookie", cookie)
        self.end_headers()
        self.wfile.write(body)

    def body_json(self):
        n = int(self.headers.get("Content-Length", "0") or 0)
        if n <= 0:
            return {}
        try:
            return json.loads(self.rfile.read(n).decode())
        except Exception:
            return {}

    def do_GET(self):
        path = urlparse(self.path).path
        if path in ("/", "/admin", "/index.html"):
            body = PAGE.encode()
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return
        if path == "/healthz":
            self.send_json({"ok": True})
            return
        c = db(); expire_codes(c); c.commit()
        try:
            self.api_get(c, path)
        finally:
            c.close()

    def do_POST(self):
        path = urlparse(self.path).path
        c = db(); expire_codes(c)
        try:
            self.api_post(c, path)
            c.commit()
        finally:
            c.close()

    # ---------- helpers ----------
    def need_admin(self, c):
        s = read_session(c, self)
        if not s or s["role"] != "admin":
            self.send_json({"error": "需要管理员登录"}, 401)
            return None
        return s

    def need_customer(self, c):
        s = read_session(c, self)
        if not s or s["role"] != "customer":
            self.send_json({"error": "需要顾客登录"}, 401)
            return None
        row = c.execute("SELECT * FROM customers WHERE id=?", (s["customer_id"],)).fetchone()
        if not row or not row["active"]:
            self.send_json({"error": "账号已停用或不存在"}, 403)
            return None
        return row

    def session_cookie(self, token):
        return f"otp_session={token}; Path=/; HttpOnly; SameSite=Lax; Max-Age={SESSION_TTL}"

    # ---------- GET APIs ----------
    def api_get(self, c, path):
        if path == "/api/state":
            has_admin = c.execute("SELECT id FROM admin WHERE id=1").fetchone() is not None
            s = read_session(c, self)
            role = s["role"] if s else None
            cust = None
            if s and s["role"] == "customer":
                r = c.execute("SELECT username, display_name FROM customers WHERE id=?", (s["customer_id"],)).fetchone()
                cust = dict(r) if r else None
            self.send_json({"has_admin": has_admin, "role": role, "customer": cust,
                            "site_name": get_setting(c, "site_name", "OTP CENTER")})
            return
        if path == "/api/admin/overview":
            if not self.need_admin(c): return
            t = now(); day = t - (t % 86400)
            q = lambda sql, a=(): c.execute(sql, a).fetchone()[0]
            self.send_json({
                "customers": q("SELECT COUNT(*) FROM customers"),
                "orders": q("SELECT COUNT(*) FROM orders"),
                "codes_total": q("SELECT COUNT(*) FROM codes"),
                "codes_used": q("SELECT COUNT(*) FROM codes WHERE status='已核销'"),
                "codes_expired": q("SELECT COUNT(*) FROM codes WHERE status='已过期'"),
                "codes_today": q("SELECT COUNT(*) FROM codes WHERE created_at>=?", (day,)),
            })
            return
        if path == "/api/admin/customers":
            if not self.need_admin(c): return
            rows = c.execute("SELECT id, username, display_name, active, created_at FROM customers ORDER BY id DESC").fetchall()
            self.send_json({"customers": [dict(r) for r in rows]})
            return
        if path == "/api/admin/orders":
            if not self.need_admin(c): return
            rows = c.execute("""SELECT o.*, cu.username, cu.display_name FROM orders o
                JOIN customers cu ON cu.id=o.customer_id ORDER BY o.id DESC""").fetchall()
            self.send_json({"orders": [dict(r) for r in rows]})
            return
        if path == "/api/admin/codes":
            if not self.need_admin(c): return
            rows = c.execute("""SELECT co.*, o.order_no, cu.username FROM codes co
                JOIN orders o ON o.id=co.order_id JOIN customers cu ON cu.id=co.customer_id
                ORDER BY co.id DESC LIMIT 200""").fetchall()
            out = []
            for r in rows:
                d = dict(r); d.pop("code_hash", None); out.append(d)
            self.send_json({"codes": out})
            return
        if path == "/api/admin/audit":
            if not self.need_admin(c): return
            rows = c.execute("SELECT * FROM audit ORDER BY id DESC LIMIT 200").fetchall()
            self.send_json({"audit": [dict(r) for r in rows]})
            return
        if path == "/api/admin/settings":
            if not self.need_admin(c): return
            self.send_json({"ttl_minutes": int(get_setting(c, "ttl_minutes", "5")),
                            "per_hour_limit": int(get_setting(c, "per_hour_limit", "5")),
                            "site_name": get_setting(c, "site_name", "OTP CENTER")})
            return
        if path == "/api/my/orders":
            me = self.need_customer(c)
            if not me: return
            rows = c.execute("SELECT * FROM orders WHERE customer_id=? ORDER BY id DESC", (me["id"],)).fetchall()
            out = []
            for r in rows:
                d = dict(r)
                act = c.execute("SELECT id, expires_at FROM codes WHERE order_id=? AND status='有效' ORDER BY id DESC LIMIT 1", (r["id"],)).fetchone()
                d["has_active_code"] = bool(act)
                d["active_expires_at"] = act["expires_at"] if act else None
                out.append(d)
            self.send_json({"orders": out})
            return
        if path == "/api/my/history":
            me = self.need_customer(c)
            if not me: return
            rows = c.execute("""SELECT co.id, co.status, co.created_at, co.expires_at, co.used_at, o.order_no
                FROM codes co JOIN orders o ON o.id=co.order_id
                WHERE co.customer_id=? ORDER BY co.id DESC LIMIT 100""", (me["id"],)).fetchall()
            self.send_json({"history": [dict(r) for r in rows]})
            return
        self.send_json({"error": "not found"}, 404)

    # ---------- POST APIs ----------
    def api_post(self, c, path):
        data = self.body_json()
        if path == "/api/admin/setup":
            if c.execute("SELECT id FROM admin WHERE id=1").fetchone():
                self.send_json({"error": "管理员已设置，请直接登录"}, 400); return
            pw = (data.get("password") or "").strip()
            if len(pw) < 6:
                self.send_json({"error": "管理员口令至少 6 位"}, 400); return
            salt, h = pw_hash(pw)
            c.execute("INSERT INTO admin(id,salt,pass_hash) VALUES(1,?,?)", (salt, h))
            audit(c, "admin", "设置管理员口令")
            token = make_session(c, "admin")
            self.send_json({"ok": True}, cookie=self.session_cookie(token)); return
        if path == "/api/admin/login":
            row = c.execute("SELECT * FROM admin WHERE id=1").fetchone()
            if not row:
                self.send_json({"error": "管理员尚未设置"}, 400); return
            if not pw_check(str(data.get("password") or ""), row["salt"], row["pass_hash"]):
                audit(c, "admin", "管理员登录失败")
                self.send_json({"error": "口令不正确"}, 401); return
            token = make_session(c, "admin")
            audit(c, "admin", "管理员登录")
            self.send_json({"ok": True}, cookie=self.session_cookie(token)); return
        if path == "/api/customer/login":
            row = c.execute("SELECT * FROM customers WHERE username=?", (str(data.get("username") or "").strip(),)).fetchone()
            if not row or not pw_check(str(data.get("password") or ""), row["salt"], row["pass_hash"]):
                audit(c, str(data.get("username") or "?"), "顾客登录失败")
                self.send_json({"error": "登录名或密码不正确"}, 401); return
            if not row["active"]:
                self.send_json({"error": "账号已停用，请联系店主"}, 403); return
            token = make_session(c, "customer", row["id"])
            audit(c, row["username"], "顾客登录")
            self.send_json({"ok": True, "display_name": row["display_name"]}, cookie=self.session_cookie(token)); return
        if path == "/api/logout":
            s = read_session(c, self)
            if s:
                c.execute("DELETE FROM sessions WHERE token_hash=?", (s["token_hash"],))
            self.send_json({"ok": True}, cookie="otp_session=; Path=/; HttpOnly; Max-Age=0"); return
        if path == "/api/admin/customers":
            if not self.need_admin(c): return
            username = str(data.get("username") or "").strip()
            pw = str(data.get("password") or "")
            if not username or len(pw) < 6:
                self.send_json({"error": "登录名必填，密码至少 6 位"}, 400); return
            if c.execute("SELECT id FROM customers WHERE username=?", (username,)).fetchone():
                self.send_json({"error": "登录名已存在"}, 400); return
            salt, h = pw_hash(pw)
            c.execute("INSERT INTO customers(username,display_name,salt,pass_hash,active,created_at) VALUES(?,?,?,?,1,?)",
                      (username, str(data.get("display_name") or username), salt, h, now()))
            audit(c, "admin", "新建顾客", username)
            self.send_json({"ok": True}); return
        if path == "/api/admin/customers/toggle":
            if not self.need_admin(c): return
            row = c.execute("SELECT * FROM customers WHERE id=?", (data.get("id"),)).fetchone()
            if not row:
                self.send_json({"error": "顾客不存在"}, 404); return
            newv = 0 if row["active"] else 1
            c.execute("UPDATE customers SET active=? WHERE id=?", (newv, row["id"]))
            audit(c, "admin", "顾客启用/停用", f"{row['username']} -> {newv}")
            self.send_json({"ok": True, "active": newv}); return
        if path == "/api/admin/orders":
            if not self.need_admin(c): return
            cust = c.execute("SELECT * FROM customers WHERE id=?", (data.get("customer_id"),)).fetchone()
            if not cust:
                self.send_json({"error": "请选择顾客"}, 400); return
            order_no = "OTP" + time.strftime("%Y%m%d") + secrets.token_hex(3).upper()
            c.execute("INSERT INTO orders(order_no,customer_id,item,note,status,created_at) VALUES(?,?,?,?, '进行中', ?)",
                      (order_no, cust["id"], str(data.get("item") or ""), str(data.get("note") or ""), now()))
            audit(c, "admin", "新建订单", order_no + " -> " + cust["username"])
            self.send_json({"ok": True, "order_no": order_no}); return
        if path == "/api/admin/orders/status":
            if not self.need_admin(c): return
            st = str(data.get("status") or "")
            if st not in ("进行中", "已完成", "已取消"):
                self.send_json({"error": "状态不正确"}, 400); return
            c.execute("UPDATE orders SET status=? WHERE id=?", (st, data.get("id")))
            audit(c, "admin", "订单状态变更", f"#{data.get('id')} -> {st}")
            self.send_json({"ok": True}); return
        if path == "/api/admin/codes/revoke":
            if not self.need_admin(c): return
            row = c.execute("SELECT * FROM codes WHERE id=? AND status='有效'", (data.get("id"),)).fetchone()
            if not row:
                self.send_json({"error": "该码不存在或已不是有效状态"}, 400); return
            c.execute("UPDATE codes SET status='已撤销' WHERE id=?", (row["id"],))
            audit(c, "admin", "撤销验证码", f"code#{row['id']}")
            self.send_json({"ok": True}); return
        if path == "/api/admin/verify":
            if not self.need_admin(c): return
            order_no = str(data.get("order_no") or "").strip()
            code = str(data.get("code") or "").strip()
            o = c.execute("SELECT * FROM orders WHERE order_no=?", (order_no,)).fetchone()
            if not o:
                self.send_json({"error": "订单不存在"}, 404); return
            ch = code_hash(code, order_no)
            row = c.execute("SELECT * FROM codes WHERE order_id=? AND code_hash=? ORDER BY id DESC LIMIT 1", (o["id"], ch)).fetchone()
            if not row:
                audit(c, "admin", "核销失败-码不匹配", order_no)
                self.send_json({"error": "验证码不正确"}, 400); return
            if row["status"] == "已核销":
                self.send_json({"error": "该码已核销，不能重复使用"}, 400); return
            if row["status"] != "有效" or row["expires_at"] < now():
                self.send_json({"error": "该码已过期或已撤销"}, 400); return
            c.execute("UPDATE codes SET status='已核销', used_at=? WHERE id=?", (now(), row["id"]))
            audit(c, "admin", "核销成功", order_no)
            self.send_json({"ok": True, "message": "核销成功"}); return
        if path == "/api/admin/settings":
            if not self.need_admin(c): return
            ttl = int(data.get("ttl_minutes") or 5)
            lim = int(data.get("per_hour_limit") or 5)
            if ttl < 1 or ttl > 60 or lim < 1 or lim > 50:
                self.send_json({"error": "有效期 1-60 分钟，每小时上限 1-50 次"}, 400); return
            c.execute("INSERT OR REPLACE INTO settings(key,value) VALUES('ttl_minutes',?)", (str(ttl),))
            c.execute("INSERT OR REPLACE INTO settings(key,value) VALUES('per_hour_limit',?)", (str(lim),))
            if data.get("site_name"):
                c.execute("INSERT OR REPLACE INTO settings(key,value) VALUES('site_name',?)", (str(data["site_name"])[:40],))
            audit(c, "admin", "修改系统设置", f"ttl={ttl}, limit={lim}")
            self.send_json({"ok": True}); return
        if path == "/api/my/claim":
            me = self.need_customer(c)
            if not me: return
            o = c.execute("SELECT * FROM orders WHERE id=? AND customer_id=?", (data.get("order_id"), me["id"])).fetchone()
            if not o:
                self.send_json({"error": "订单不存在或不属于你"}, 404); return
            if o["status"] != "进行中":
                self.send_json({"error": "该订单当前状态不能取码"}, 400); return
            act = c.execute("SELECT * FROM codes WHERE order_id=? AND status='有效' AND expires_at>=? ORDER BY id DESC LIMIT 1",
                            (o["id"], now())).fetchone()
            if act:
                self.send_json({"error": "已有未过期的验证码，请等它过期或被核销后再取", "expires_at": act["expires_at"]}, 400); return
            lim = int(get_setting(c, "per_hour_limit", "5"))
            cnt = c.execute("SELECT COUNT(*) FROM codes WHERE order_id=? AND created_at>=?", (o["id"], now() - 3600)).fetchone()[0]
            if cnt >= lim:
                audit(c, me["username"], "取码被限流", o["order_no"])
                self.send_json({"error": f"取码太频繁：每个订单每小时最多 {lim} 次"}, 429); return
            ttl = int(get_setting(c, "ttl_minutes", "5"))
            code = f"{secrets.randbelow(1000000):06d}"
            exp = now() + ttl * 60
            c.execute("INSERT INTO codes(order_id,customer_id,code_hash,status,created_at,expires_at) VALUES(?,?,?,'有效',?,?)",
                      (o["id"], me["id"], code_hash(code, o["order_no"]), now(), exp))
            audit(c, me["username"], "生成验证码", o["order_no"])
            self.send_json({"ok": True, "code": code, "order_no": o["order_no"], "expires_at": exp, "ttl_minutes": ttl}); return
        self.send_json({"error": "not found"}, 404)

PAGE = r"""<!DOCTYPE html>
<html lang="zh-CN"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>OTP CENTER · 自有业务验证码中心</title>
<style>
:root{--bg:#070b16;--panel:#0e1628;--panel2:#111c33;--line:#1e2c4a;--txt:#e8eefc;--sub:#8fa3c8;--acc:#3b82f6;--acc2:#22d3ee;--ok:#34d399;--bad:#f87171;--warn:#fbbf24}
*{box-sizing:border-box}body{margin:0;font-family:-apple-system,"PingFang SC","Microsoft YaHei",sans-serif;background:radial-gradient(1000px 500px at 80% -10%,#16295c 0,transparent 60%),radial-gradient(800px 400px at -10% 10%,#0b2b3a 0,transparent 55%),var(--bg);color:var(--txt);min-height:100vh}
.wrap{max-width:1060px;margin:0 auto;padding:18px 14px 48px}
.brand{display:flex;align-items:center;gap:12px;padding:10px 2px 18px}
.logo{width:42px;height:42px;border-radius:12px;background:linear-gradient(135deg,var(--acc),var(--acc2));display:flex;align-items:center;justify-content:center;font-size:20px;box-shadow:0 8px 24px rgba(59,130,246,.4)}
.brand h1{font-size:20px;margin:0;letter-spacing:2px}.brand p{margin:2px 0 0;color:var(--sub);font-size:12px}
.tabs{display:flex;gap:8px;margin-bottom:16px}
.tabs button{flex:1;padding:11px;border-radius:12px;border:1px solid var(--line);background:var(--panel);color:var(--sub);font-size:15px;cursor:pointer}
.tabs button.on{background:linear-gradient(135deg,#1d4ed8,#0e7490);color:#fff;border-color:transparent}
.card{background:linear-gradient(180deg,var(--panel2),var(--panel));border:1px solid var(--line);border-radius:16px;padding:18px;margin-bottom:14px;box-shadow:0 10px 30px rgba(0,0,0,.35)}
.card h2{margin:0 0 12px;font-size:16px}.card h3{margin:0 0 8px;font-size:14px}
input,select,textarea{width:100%;padding:11px 12px;border-radius:10px;border:1px solid var(--line);background:#0a1222;color:var(--txt);font-size:15px;margin-bottom:10px}
button.btn{width:100%;padding:12px;border:0;border-radius:12px;background:linear-gradient(135deg,var(--acc),#2563eb);color:#fff;font-size:15px;font-weight:600;cursor:pointer}
button.btn:disabled{opacity:.5}
button.ghost{width:auto;padding:7px 14px;border-radius:9px;border:1px solid var(--line);background:transparent;color:var(--sub);cursor:pointer;font-size:13px}
button.mini{width:auto;padding:7px 12px;font-size:13px}
.row{display:flex;gap:10px;flex-wrap:wrap}.row>*{flex:1;min-width:140px}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px}
.stat{background:#0a1327;border:1px solid var(--line);border-radius:14px;padding:14px}.stat b{font-size:24px;display:block}.stat span{color:var(--sub);font-size:12px}
table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:8px 6px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}
th{color:var(--sub);font-weight:500}.scroll{overflow-x:auto}
.tag{display:inline-block;padding:2px 9px;border-radius:99px;font-size:12px;border:1px solid var(--line)}
.tag.ok{color:var(--ok);border-color:var(--ok)}.tag.bad{color:var(--bad);border-color:var(--bad)}.tag.warn{color:var(--warn);border-color:var(--warn)}
.codebox{text-align:center;padding:18px 8px}.bigcode{font-size:44px;letter-spacing:10px;font-weight:800;background:linear-gradient(90deg,#60a5fa,#22d3ee);-webkit-background-clip:text;background-clip:text;color:transparent}
.msg{min-height:20px;font-size:13px;color:var(--warn);margin:8px 0}.okmsg{color:var(--ok)}
.note{color:var(--sub);font-size:12px;line-height:1.7}.hide{display:none}
.subtabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}.subtabs button{padding:8px 14px;border-radius:99px;border:1px solid var(--line);background:var(--panel);color:var(--sub);cursor:pointer}.subtabs button.on{background:#1d4ed8;color:#fff;border-color:transparent}
</style></head><body><div class="wrap">
<div class="brand"><div class="logo">🔐</div><div><h1>OTP CENTER</h1><p>自有业务验证码中心 · 码由本站服务端签发，不读取任何外部邮箱</p></div></div>
<div class="tabs"><button id="tabCust" class="on" onclick="showView('cust')">顾客端</button><button id="tabAdmin" onclick="showView('admin')">管理员后台</button></div>

<!-- 顾客端 -->
<div id="viewCust">
  <div class="card" id="custLoginCard"><h2>顾客登录</h2>
    <input id="cu_name" placeholder="登录名"><input id="cu_pw" type="password" placeholder="密码">
    <div class="msg" id="cu_msg"></div><button class="btn" onclick="custLogin()">登录</button>
    <p class="note">账号由店主在管理员后台创建。登录后只能看到分配给你的订单。</p></div>
  <div id="custMain" class="hide">
    <div class="card"><div class="row" style="align-items:center"><div><h2 style="margin:0">我的订单</h2><p class="note" id="custWho"></p></div><button class="ghost" onclick="logout()">退出登录</button></div>
      <div id="myOrders"></div></div>
    <div class="card hide" id="codeCard"><h2>你的验证码</h2><div class="codebox">
      <div class="bigcode" id="bigCode">------</div>
      <p class="note" id="codeMeta"></p>
      <button class="btn mini" onclick="copyCode()">一键复制验证码</button>
      <p class="note">验证码只显示这一次，过期或被核销后失效，不能重复使用。</p></div></div>
    <div class="card"><h2>取码历史</h2><div class="scroll"><table><thead><tr><th>订单号</th><th>生成时间</th><th>到期</th><th>状态</th></tr></thead><tbody id="myHist"></tbody></table></div></div>
  </div>
</div>

<!-- 管理员 -->
<div id="viewAdmin" class="hide">
  <div class="card" id="adminGate"><h2 id="gateTitle">管理员登录</h2>
    <input id="ad_pw" type="password" placeholder="管理员口令">
    <div class="msg" id="ad_msg"></div><button class="btn" id="gateBtn" onclick="adminGate()">进入后台</button>
    <p class="note" id="gateNote">首次使用时，这里设置管理员口令（至少 6 位），请记牢。</p></div>
  <div id="adminMain" class="hide">
    <div class="subtabs">
      <button data-st="overview" class="on" onclick="adminTab('overview')">数据总览</button>
      <button data-st="customers" onclick="adminTab('customers')">顾客账号</button>
      <button data-st="orders" onclick="adminTab('orders')">订单管理</button>
      <button data-st="codes" onclick="adminTab('codes')">验证码记录</button>
      <button data-st="verify" onclick="adminTab('verify')">核销验证</button>
      <button data-st="audit" onclick="adminTab('audit')">审计日志</button>
      <button data-st="settings" onclick="adminTab('settings')">系统设置</button>
      <button onclick="logout()">退出</button>
    </div>
    <div id="at_overview" class="card"><h2>数据总览</h2><div class="grid" id="ovGrid"></div>
      <p class="note">使用流程：建顾客 → 建订单 → 顾客在顾客端登录取码 → 你在这里核销验证。</p></div>
    <div id="at_customers" class="card hide"><h2>新建顾客</h2>
      <div class="row"><input id="nc_user" placeholder="登录名"><input id="nc_name" placeholder="显示名（可选）"><input id="nc_pw" placeholder="登录密码（至少6位）"></div>
      <div class="msg" id="nc_msg"></div><button class="btn" onclick="createCustomer()">创建顾客</button>
      <h3 style="margin-top:18px">顾客列表</h3><div class="scroll"><table><thead><tr><th>登录名</th><th>显示名</th><th>状态</th><th>操作</th></tr></thead><tbody id="custList"></tbody></table></div></div>
    <div id="at_orders" class="card hide"><h2>新建订单</h2>
      <div class="row"><select id="no_cust"></select><input id="no_item" placeholder="商品 / 服务名称"><input id="no_note" placeholder="备注（可选）"></div>
      <div class="msg" id="no_msg"></div><button class="btn" onclick="createOrder()">创建订单</button>
      <h3 style="margin-top:18px">订单列表</h3><div class="scroll"><table><thead><tr><th>订单号</th><th>顾客</th><th>商品</th><th>状态</th><th>操作</th></tr></thead><tbody id="ordList"></tbody></table></div></div>
    <div id="at_codes" class="card hide"><h2>验证码记录</h2><div class="scroll"><table><thead><tr><th>订单号</th><th>顾客</th><th>生成</th><th>到期</th><th>状态</th><th>操作</th></tr></thead><tbody id="codeList"></tbody></table></div></div>
    <div id="at_verify" class="card hide"><h2>核销验证</h2>
      <div class="row"><input id="vf_no" placeholder="订单号"><input id="vf_code" placeholder="顾客给的 6 位验证码"></div>
      <div class="msg" id="vf_msg"></div><button class="btn" onclick="verifyCode()">核销</button>
      <p class="note">核销成功后该码立即失效，不能再次使用。</p></div>
    <div id="at_audit" class="card hide"><h2>审计日志</h2><div class="scroll"><table><thead><tr><th>时间</th><th>操作者</th><th>动作</th><th>详情</th></tr></thead><tbody id="auditList"></tbody></table></div></div>
    <div id="at_settings" class="card hide"><h2>系统设置</h2>
      <div class="row"><div><label class="note">验证码有效期（分钟）</label><input id="st_ttl" type="number"></div>
      <div><label class="note">每订单每小时最多生成（次）</label><input id="st_lim" type="number"></div>
      <div><label class="note">站点名称</label><input id="st_name"></div></div>
      <div class="msg" id="st_msg"></div><button class="btn" onclick="saveSettings()">保存设置</button></div>
  </div>
</div>
<p class="note" style="text-align:center">OTP CENTER · 验证码由本站服务端生成并与订单绑定 · 不导入第三方邮箱凭据 · 不读取外部邮箱</p>
</div>
<script>
const $=id=>document.getElementById(id);
async function api(path,opts={}){const r=await fetch(path,{headers:{'Content-Type':'application/json'},...opts});let d={};try{d=await r.json()}catch(e){}return{r,d}}
const fmt=t=>t?new Date(t*1000).toLocaleString('zh-CN',{hour12:false}):'-';
let lastCode='',countTimer=null;
function showView(v){$('viewCust').classList.toggle('hide',v!=='cust');$('viewAdmin').classList.toggle('hide',v!=='admin');$('tabCust').classList.toggle('on',v==='cust');$('tabAdmin').classList.toggle('on',v==='admin');if(v==='admin')initAdmin();}
async function boot(){const{d}=await api('/api/state');window._state=d;
  if(d.role==='customer'){showCustMain(d.customer)} if(d.role==='admin'){$('adminGate').classList.add('hide');$('adminMain').classList.remove('hide');loadOverview();}
  if(!d.has_admin){$('gateTitle').textContent='设置管理员口令（首次）';$('gateBtn').textContent='设置并进入后台';}}
async function custLogin(){const{d,r}=await api('/api/customer/login',{method:'POST',body:JSON.stringify({username:$('cu_name').value,password:$('cu_pw').value})});
  if(!r.ok){$('cu_msg').textContent=d.error||'登录失败';return}$('cu_msg').textContent='';showCustMain({username:$('cu_name').value,display_name:d.display_name});}
function showCustMain(cust){$('custLoginCard').classList.add('hide');$('custMain').classList.remove('hide');$('custWho').textContent='当前账号：'+(cust.display_name||cust.username);loadMy();}
async function logout(){await api('/api/logout',{method:'POST',body:'{}'});location.reload();}
async function loadMy(){const{d}=await api('/api/my/orders');const box=$('myOrders');
  if(!d.orders||!d.orders.length){box.innerHTML='<p class="note">暂无订单，请联系店主创建订单。</p>'}
  else box.innerHTML=d.orders.map(o=>`<div style="border:1px solid var(--line);border-radius:12px;padding:12px;margin-bottom:10px">
    <b>${o.order_no}</b> <span class="tag ${o.status==='进行中'?'ok':o.status==='已取消'?'bad':'warn'}">${o.status}</span>
    <p class="note" style="margin:6px 0">${o.item||''} ${o.note||''}<br>创建时间：${fmt(o.created_at)}${o.has_active_code?'<br>已有有效验证码，到期：'+fmt(o.active_expires_at):''}</p>
    <button class="btn mini" ${o.status!=='进行中'?'disabled':''} onclick="claim(${o.id})">获取验证码</button></div>`).join('');
  const h=await api('/api/my/history');$('myHist').innerHTML=(h.d.history||[]).map(x=>`<tr><td>${x.order_no}</td><td>${fmt(x.created_at)}</td><td>${fmt(x.expires_at)}</td><td>${x.status}</td></tr>`).join('')||'<tr><td colspan="4" class="note">暂无记录</td></tr>';}
async function claim(orderId){const{d,r}=await api('/api/my/claim',{method:'POST',body:JSON.stringify({order_id:orderId})});
  if(!r.ok){alert(d.error||'取码失败');loadMy();return}
  lastCode=d.code;$('codeCard').classList.remove('hide');$('bigCode').textContent=d.code;
  const tick=()=>{const left=d.expires_at-Math.floor(Date.now()/1000);$('codeMeta').textContent='订单 '+d.order_no+' · 剩余 '+Math.max(0,left)+' 秒 · 到期 '+fmt(d.expires_at);if(left<=0){clearInterval(countTimer);$('codeMeta').textContent='已过期，请重新获取';loadMy();}};
  clearInterval(countTimer);tick();countTimer=setInterval(tick,1000);loadMy();}
function copyCode(){if(lastCode)navigator.clipboard.writeText(lastCode).then(()=>alert('已复制 '+lastCode));}
async function initAdmin(){const{d}=await api('/api/state');if(d.role==='admin'){$('adminGate').classList.add('hide');$('adminMain').classList.remove('hide');loadOverview();return}
  if(!d.has_admin){$('gateTitle').textContent='设置管理员口令（首次）';$('gateBtn').textContent='设置并进入后台';}}
async function adminGate(){const{d}=await api('/api/state');const path=d.has_admin?'/api/admin/login':'/api/admin/setup';
  const{ d:res, r }=await api(path,{method:'POST',body:JSON.stringify({password:$('ad_pw').value})});
  if(!r.ok){$('ad_msg').textContent=res.error||'失败';return}$('adminGate').classList.add('hide');$('adminMain').classList.remove('hide');loadOverview();}
function adminTab(t){document.querySelectorAll('[data-st]').forEach(b=>b.classList.toggle('on',b.dataset.st===t));
  ['overview','customers','orders','codes','verify','audit','settings'].forEach(x=>$('at_'+x).classList.toggle('hide',x!==t));
  if(t==='overview')loadOverview();if(t==='customers')loadCustomers();if(t==='orders'){loadOrders();fillCustSelect();}if(t==='codes')loadCodes();if(t==='audit')loadAudit();if(t==='settings')loadSettings();}
async function loadOverview(){const{d}=await api('/api/admin/overview');const items=[['顾客数',d.customers],['订单数',d.orders],['验证码总数',d.codes_total],['已核销',d.codes_used],['已过期',d.codes_expired],['今日生成',d.codes_today]];
  $('ovGrid').innerHTML=items.map(x=>`<div class="stat"><b>${x[1]??0}</b><span>${x[0]}</span></div>`).join('');}
async function loadCustomers(){const{d}=await api('/api/admin/customers');window._custs=d.customers||[];
  $('custList').innerHTML=window._custs.map(x=>`<tr><td>${x.username}</td><td>${x.display_name||''}</td><td>${x.active?'启用':'停用'}</td><td><button class="ghost" onclick="toggleCust(${x.id})">${x.active?'停用':'启用'}</button></td></tr>`).join('')||'<tr><td colspan="4" class="note">暂无顾客</td></tr>';}
async function createCustomer(){const{d,r}=await api('/api/admin/customers',{method:'POST',body:JSON.stringify({username:$('nc_user').value,display_name:$('nc_name').value,password:$('nc_pw').value})});
  $('nc_msg').textContent=r.ok?'创建成功':(d.error||'失败');$('nc_msg').className='msg '+(r.ok?'okmsg':'');if(r.ok)loadCustomers();}
async function toggleCust(id){await api('/api/admin/customers/toggle',{method:'POST',body:JSON.stringify({id})});loadCustomers();}
function fillCustSelect(){if(!window._custs)loadCustomers().then(fillCustSelect);else $('no_cust').innerHTML=window._custs.filter(x=>x.active).map(x=>`<option value="${x.id}">${x.username}（${x.display_name||''}）</option>`).join('');}
async function loadOrders(){const{d}=await api('/api/admin/orders');$('ordList').innerHTML=(d.orders||[]).map(o=>`<tr><td>${o.order_no}</td><td>${o.username}</td><td>${o.item||''}</td><td>${o.status}</td><td>
  <select style="width:auto;padding:5px;margin:0" onchange="setStatus(${o.id},this.value)"><option ${o.status==='进行中'?'selected':''}>进行中</option><option ${o.status==='已完成'?'selected':''}>已完成</option><option ${o.status==='已取消'?'selected':''}>已取消</option></select></td></tr>`).join('')||'<tr><td colspan="5" class="note">暂无订单</td></tr>';}
async function createOrder(){const{d,r}=await api('/api/admin/orders',{method:'POST',body:JSON.stringify({customer_id:Number($('no_cust').value),item:$('no_item').value,note:$('no_note').value})});
  $('no_msg').textContent=r.ok?('创建成功，订单号 '+d.order_no):(d.error||'失败');$('no_msg').className='msg '+(r.ok?'okmsg':'');if(r.ok)loadOrders();}
async function setStatus(id,st){await api('/api/admin/orders/status',{method:'POST',body:JSON.stringify({id,status:st})});loadOrders();}
async function loadCodes(){const{d}=await api('/api/admin/codes');$('codeList').innerHTML=(d.codes||[]).map(x=>`<tr><td>${x.order_no}</td><td>${x.username}</td><td>${fmt(x.created_at)}</td><td>${fmt(x.expires_at)}</td><td>${x.status}</td><td>${x.status==='有效'?`<button class="ghost" onclick="revokeCode(${x.id})">撤销</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="note">暂无记录</td></tr>';}
async function revokeCode(id){await api('/api/admin/codes/revoke',{method:'POST',body:JSON.stringify({id})});loadCodes();}
async function verifyCode(){const{d,r}=await api('/api/admin/verify',{method:'POST',body:JSON.stringify({order_no:$('vf_no').value,code:$('vf_code').value})});
  $('vf_msg').textContent=r.ok?'✅ 核销成功':(d.error||'核销失败');$('vf_msg').className='msg '+(r.ok?'okmsg':'');}
async function loadAudit(){const{d}=await api('/api/admin/audit');$('auditList').innerHTML=(d.audit||[]).map(x=>`<tr><td>${fmt(x.ts)}</td><td>${x.actor}</td><td>${x.action}</td><td>${x.detail||''}</td></tr>`).join('');}
async function loadSettings(){const{d}=await api('/api/admin/settings');$('st_ttl').value=d.ttl_minutes;$('st_lim').value=d.per_hour_limit;$('st_name').value=d.site_name;}
async function saveSettings(){const{d,r}=await api('/api/admin/settings',{method:'POST',body:JSON.stringify({ttl_minutes:Number($('st_ttl').value),per_hour_limit:Number($('st_lim').value),site_name:$('st_name').value})});
  $('st_msg').textContent=r.ok?'已保存':(d.error||'失败');}
boot();
</script></body></html>
"""

if __name__ == "__main__":
    init_db()
    ThreadingHTTPServer(("0.0.0.0", PORT), Handler).serve_forever()
